def name_operands(region,function_address,operation):
    if region=='Action':
        for address,name in ((0xE021,'@ActionProjectedBoundsState.CompanionMask'),
            (0xE372,'@ActionProjectedBoundsState.AbsoluteX'),(0xE375,'@ActionProjectedBoundsState.AbsoluteY')):
            operation=operation.replace('(#'+format(address,'04X')+')','('+name+')')
    if region=='Action' and function_address==0xE299:
        for address,name in ((0xD9B6,'@ActionPatchedVectorState.Output0'),(0xD7C4,'@ActionPatchedVectorState.Output1'),
            (0xD7A2,'@ActionPatchedVectorState.Output2'),(0xE310,'@ActionProjectedCaptureState.Gate'),
            (0xE331,'@ActionProjectedCaptureState.Limit'),(0xE33A,'@ActionProjectedCaptureState.ProjectedX')):
            operation=operation.replace('(#'+format(address,'04X')+')','('+name+')')
        operation=operation.replace('(#D9B7)','(@ActionPatchedVectorState.Output0 + 1)')
        operation=operation.replace('(#D7C5)','(@ActionPatchedVectorState.Output1 + 1)')
        operation=operation.replace('CP #0A','CP @ActionProjectedBoundsConst.HighByteLimit')
    return operation
